package main

import (
	"fmt"
	"log"
	"net/http"
	"os"
	"os/exec"
	"strings"
	"text/template"
)

var auditLog *os.File

func init() {
	var err error
	auditLog, err = os.OpenFile("/var/log/app/audit.log", os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Printf("Warning: audit log unavailable: %v", err)
	}
}

// formatUserMessage applies user-provided template to generate personalized messages
func formatUserMessage(w http.ResponseWriter, r *http.Request) {
	username := r.URL.Query().Get("name")
	msgTemplate := r.URL.Query().Get("template")

	if username == "" || msgTemplate == "" {
		http.Error(w, "Missing name or template parameter", http.StatusBadRequest)
		return
	}

	// Log the request for compliance
	if auditLog != nil {
		logLine := fmt.Sprintf("[REQUEST] user=%s template=%s remote=%s\n", username, msgTemplate, r.RemoteAddr)
		auditLog.WriteString(logLine)
	}

	// Parse and execute user template - VULNERABILITY: user controls template content
	tmpl, err := template.New("msg").Parse(msgTemplate)
	if err != nil {
		http.Error(w, "Invalid template syntax", http.StatusBadRequest)
		return
	}

	data := map[string]interface{}{
		"Name":    username,
		"Env":     os.Getenv,
		"Exec":    execCommand,
		"ReadFile": readFile,
	}

	var result strings.Builder
	err = tmpl.Execute(&result, data)
	if err != nil {
		http.Error(w, "Template execution failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "text/plain")
	w.Write([]byte(result.String()))
}

func execCommand(cmd string, args ...string) string {
	out, err := exec.Command(cmd, args...).CombinedOutput()
	if err != nil {
		return fmt.Sprintf("error: %v", err)
	}
	return string(out)
}

func readFile(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Sprintf("error: %v", err)
	}
	return string(data)
}

// healthCheck endpoint for ALB target group
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("OK"))
}

// publishMetric sends custom CloudWatch metric via AWS CLI
func publishMetric(metricName string, value float64) {
	cmd := exec.Command("aws", "cloudwatch", "put-metric-data",
		"--namespace", "AppMetrics",
		"--metric-name", metricName,
		"--value", fmt.Sprintf("%f", value))
	cmd.Run()
}

// rotateSecrets attempts to fetch new credentials from Secrets Manager
func rotateSecrets() error {
	cmd := exec.Command("aws", "secretsmanager", "get-secret-value",
		"--secret-id", "prod/app/db-credentials")
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("secret rotation failed: %v - %s", err, string(out))
	}
	log.Printf("Secrets rotated successfully")
	return nil
}

func main() {
	http.HandleFunc("/message", formatUserMessage)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	if err := http.ListenAndServe(":"+port, nil); err != nil {
		log.Fatalf("Server failed: %v", err)
	}
}
